<script setup lang="ts">
import { computed, ref, onMounted, onUnmounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useQuery, useQueryClient } from '@tanstack/vue-query'
import { Building2, Home, Wallet, Megaphone, UserRound, Wrench, FileText, Shield, LogOut, Siren, AlertTriangle, Phone, Plus } from '@lucide/vue'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import FormDialog, { type Field } from '@/components/FormDialog.vue'
import { get, post, message, currency, date, statusName, fileData, type Row } from '@/lib/api'
import { useAuth } from '@/stores/auth'
const route=useRoute(),router=useRouter(),auth=useAuth(),client=useQueryClient()
const section=computed(()=>String(route.params.section||'home'))
const menu=[{id:'home',label:'หน้าหลัก',icon:Home},{id:'bills',label:'บิลของฉัน',icon:Wallet},{id:'announcements',label:'ประกาศ',icon:Megaphone},{id:'account',label:'บัญชี',icon:UserRound}]
const quick=[{id:'maintenance',label:'แจ้งซ่อมห้อง',icon:Wrench},{id:'incidents',label:'ส่วนกลางชำรุด',icon:AlertTriangle},{id:'documents',label:'สัญญาเช่า',icon:FileText},{id:'rules',label:'กฎระเบียบ',icon:Shield},{id:'moveouts',label:'ย้ายออก',icon:LogOut},{id:'emergency',label:'ฉุกเฉิน',icon:Siren}]
const title=computed(()=>({home:'หน้าหลัก',bills:'บิลของฉัน',maintenance:'แจ้งซ่อมห้อง',incidents:'รายงานปัญหาส่วนกลาง',announcements:'ประกาศ',documents:'สัญญาเช่า',rules:'กฎระเบียบ',moveouts:'คำขอย้ายออก',emergency:'ติดต่อฉุกเฉิน',account:'บัญชีของฉัน'} as Record<string,string>)[section.value]||'ข้อมูล')
async function load():Promise<Record<string,unknown>>{
  const sec=section.value
  if(sec==='home'){const [invoices,payments,units,announcements]=await Promise.all([get<Row[]>('/invoices'),get<Row[]>('/payments'),get<Row[]>('/units'),get<Row[]>('/announcements')]);return {invoices,payments,units,announcements}}
  if(sec==='bills'){const [invoices,payments,settings]=await Promise.all([get<Row[]>('/invoices'),get<Row[]>('/payments'),get<Record<string,string>>('/settings')]);return {invoices,payments,settings}}
  if(sec==='incidents'){const [incidents,properties]=await Promise.all([get<Row[]>('/incidents'),get<Row[]>('/properties')]);return {incidents,properties}}
  if(sec==='emergency')return {settings:await get<Record<string,string>>('/settings')}
  if(sec==='account')return {}
  const endpoint=({documents:'contracts',moveouts:'moveouts'} as Record<string,string>)[sec]||sec
  return {items:await get<Row[]>(`/${endpoint}`)}
}
const {data,error:loadError,isPending}=useQuery({queryKey:computed(()=>['resident',section.value]),queryFn:load})
const items=computed<Row[]>(()=>data.value?.items as Row[]||[])
const invoices=computed<Row[]>(()=>data.value?.invoices as Row[]||[])
const payments=computed<Row[]>(()=>data.value?.payments as Row[]||[])
const settings=computed<Record<string,string>>(()=>data.value?.settings as Record<string,string>||{})
const due=computed(()=>invoices.value.find(x=>x.status==='published'&&billRemaining(x)>0))
const latest=computed(()=>((data.value?.announcements as Row[]||[])[0]))
const unit=computed(()=>((data.value?.units as Row[]||[])[0]))
const form=ref<{title:string;fields:Field[];save:(values:Record<string,unknown>)=>Promise<void>;note?:string}|null>(null),notice=ref(''),error=ref('')
function open(title:string,fields:Field[],save:(values:Record<string,unknown>)=>Promise<void>,note?:string){form.value={title,fields,save:async values=>{await save(values);await client.invalidateQueries({queryKey:['resident']});notice.value='บันทึกแล้ว';error.value=''},note}}
function billRemaining(bill:Row):number{return Number(bill.amount)-payments.value.filter(x=>x.invoice_id===bill.id&&x.status==='verified').reduce((n,x)=>n+Number(x.amount),0)}
async function act(action:string,row?:Row){try{
  if(action==='maintenance')open('แจ้งซ่อมห้อง',[{name:'subject',label:'หัวข้อ'},{name:'detail',label:'รายละเอียด',type:'textarea'}],v=>post('/maintenance',v))
  if(action==='incident'){const properties=(data.value?.properties as Row[]||[]);open('รายงานปัญหาส่วนกลาง',[{name:'property_id',label:'โครงการ',type:'select',options:properties.map(x=>({value:x.id,label:String(x.name)}))},{name:'area',label:'จุดที่พบ เช่น ลิฟต์ อาคาร A'},{name:'detail',label:'รายละเอียด',type:'textarea'}],v=>post('/incidents',v))}
  if(action==='pay'&&row)open('ส่งหลักฐานชำระ',[{name:'amount',label:'ยอดชำระ (บาท)',type:'number',value:String(billRemaining(row))},{name:'sender',label:'ชื่อผู้โอน',value:auth.user?.name},{name:'transferred_at',label:'เวลาโอน',type:'datetime-local'},{name:'evidence',label:'หลักฐาน PNG, JPEG หรือ PDF',type:'file'}],async v=>post('/payments',{...v,invoice_id:row.id,evidence:await fileData(v.evidence as File)}),`งวด ${row.period} · ยอดคงเหลือ ${currency(billRemaining(row))}`)
  if(action==='sign'&&row)open('ลงนามอิเล็กทรอนิกส์',[{name:'name',label:'ชื่อผู้ลงนาม',value:auth.user?.name},{name:'password',label:'รหัสผ่านเพื่อยืนยันตัวตน',type:'password'},{name:'consent',label:'ฉันอ่าน PDF และยินยอมลงนามสัญญาฉบับนี้',type:'checkbox'}],v=>post(`/contracts/${row.id}/sign`,v),'อ่าน PDF สัญญาก่อนลงนาม ระบบจะบันทึกชื่อ เวลา และค่าแฮชเอกสาร')
  if(action==='moveout')open('ขอย้ายออก',[{name:'move_date',label:'วันย้ายออก',type:'date'},{name:'reason',label:'เหตุผล',type:'textarea'},{name:'contact',label:'เบอร์ติดต่อ',type:'tel'},{name:'preferred_time',label:'เวลานัดที่สะดวก',required:false}],v=>post('/moveouts',v))
  if(action==='password')open('เปลี่ยนรหัสผ่าน',[{name:'current',label:'รหัสผ่านเดิม',type:'password'},{name:'next',label:'รหัสผ่านใหม่อย่างน้อย 12 ตัวอักษร',type:'password'}],v=>post('/password',v))
  if(action==='ack'&&row)await post(`/moveouts/${row.id}/acknowledge`,{})
  if(action==='announcement-read'&&row)await post(`/announcements/${row.id}/read`,{})
  if(action==='rule-read'&&row)await post(`/rules/${row.id}/read`,{})
  if(['ack','announcement-read','rule-read'].includes(action)){await client.invalidateQueries({queryKey:['resident']});notice.value='บันทึกแล้ว'}
}catch(e){error.value=message(e)}}
async function logout(){await auth.logout();await router.replace('/login')}
function phone(value:unknown):string{return `tel:${String(value||'').replace(/[^+0-9]/g,'')}`}
let events:EventSource|undefined
onMounted(()=>{events=new EventSource('/api/events');events.addEventListener('incident',()=>client.invalidateQueries({queryKey:['resident','incidents']}))})
onUnmounted(()=>events?.close())
</script>
<template><div class="resident-shell"><header class="bg-white h-[70px] px-5 flex items-center justify-between"><strong class="text-lg flex gap-2 items-center"><Building2 class="brand" :size="23" />{{ auth.user?.organization }}</strong><RouterLink to="/app/announcements" aria-label="ประกาศ"><Megaphone :size="20" /></RouterLink></header><main class="p-5"><h1 class="text-2xl font-bold mb-1">{{ section==='home'?`สวัสดี ${auth.user?.name}`:title }}</h1><p class="text-sm text-slate-500 mb-5">{{ section==='home'?`ห้อง ${unit?.number||'—'} · อาคาร ${unit?.building||'—'}`:'ข้อมูลของ '+auth.user?.organization }}</p><p v-if="loadError" class="error-text">{{ message(loadError) }}</p><p v-if="error" class="error-text">{{ error }}</p><p v-if="notice" class="bg-emerald-50 text-emerald-800 rounded-lg p-3 mb-4">{{ notice }}</p><p v-if="isPending" class="text-slate-500">กำลังโหลด…</p>
<template v-if="section==='home'"><div class="brand-bg rounded-2xl p-5 text-white mb-4"><p>ค่าใช้จ่ายที่รอชำระ</p><strong class="text-3xl block my-2">{{ currency(due?billRemaining(due):0) }}</strong><small>{{ due?`ครบกำหนด ${date(due.due)}`:'ไม่มีบิลค้างชำระ' }}</small><RouterLink to="/app/bills" class="block bg-white/15 text-center rounded-lg py-2 mt-4">ดูบิลและสถานะ →</RouterLink></div><div class="quick-grid mb-5"><RouterLink v-for="link in quick" :key="link.id" :to="`/app/${link.id}`" class="quick-link"><component :is="link.icon" class="brand" :size="22" />{{ link.label }}</RouterLink></div><Card v-if="latest"><CardHeader><CardTitle class="text-lg">ข่าวสารจากอาคาร</CardTitle></CardHeader><CardContent><strong>{{ latest.title }}</strong><p class="text-sm text-slate-500 mt-2">{{ latest.body }}</p><RouterLink to="/app/announcements" class="brand text-sm">ดูทั้งหมด →</RouterLink></CardContent></Card></template>
<template v-else-if="section==='bills'"><Card v-for="bill in invoices" :key="bill.id" class="mb-3"><CardContent class="pt-5"><div class="flex justify-between"><strong>งวด {{ bill.period }}</strong><span class="pill">{{ statusName(bill.status) }}</span></div><div class="flex justify-between py-3 border-b"><span>ยอดบิล</span><strong>{{ currency(bill.amount) }}</strong></div><div class="flex justify-between py-3 border-b"><span>คงเหลือ</span><strong>{{ currency(billRemaining(bill)) }}</strong></div><p class="text-sm text-slate-500 my-3">ครบกำหนด {{ date(bill.due) }}</p><Button v-if="bill.status==='published'&&billRemaining(bill)>0" class="brand-bg text-white w-full" @click="act('pay',bill)">ส่งหลักฐานชำระ</Button></CardContent></Card><p v-if="!invoices.length" class="text-slate-500">ยังไม่มีบิล</p><Card v-if="settings.bank_number"><CardContent class="pt-5"><strong>บัญชีรับชำระ</strong><p>{{ settings.bank_name }} · {{ settings.bank_account }}</p><p class="font-bold">{{ settings.bank_number }}</p></CardContent></Card></template>
<template v-else-if="section==='emergency'"><p class="text-slate-500 mb-4">โทรหาเจ้าหน้าที่โดยตรงเมื่อเกิดเหตุเร่งด่วน</p><Card v-for="contact in [{label:'รปภ. 24 ชั่วโมง',number:settings.security_phone},{label:'เบอร์ฉุกเฉินของอาคาร',number:settings.emergency_phone},{label:'สำนักงานนิติบุคคล',number:settings.office_phone}]" :key="contact.label" class="mb-3"><CardContent class="pt-5"><strong>{{ contact.label }}</strong><a v-if="contact.number" :href="phone(contact.number)" class="brand-bg text-white flex items-center justify-center gap-2 rounded-lg py-3 mt-4"><Phone :size="18" />โทร {{ contact.number }}</a><p v-else class="text-slate-500 text-sm mt-2">ยังไม่ได้ตั้งค่าเบอร์</p></CardContent></Card></template>
<template v-else-if="section==='account'"><Card><CardContent class="pt-5"><p>ชื่อ: <strong>{{ auth.user?.name }}</strong></p><p>ชื่อผู้ใช้: <strong>{{ auth.user?.username }}</strong></p><div class="grid gap-2 mt-5"><Button variant="outline" @click="act('password')">เปลี่ยนรหัสผ่าน</Button><Button variant="outline" @click="logout">ออกจากระบบ</Button></div></CardContent></Card></template>
<template v-else><Button v-if="['maintenance','incidents','moveouts'].includes(section)" class="brand-bg text-white mb-4" @click="act(section==='moveouts'?'moveout':section==='incidents'?'incident':'maintenance')"><Plus :size="16" /> {{ section==='moveouts'?'ขอย้ายออก':'แจ้งรายการใหม่' }}</Button><Card v-for="row in (section==='incidents'?(data?.incidents as Row[]||[]):items)" :key="row.id" class="mb-3"><CardContent class="pt-5"><div class="flex justify-between items-start gap-2"><strong>{{ row.title||row.subject||row.area||row.number||'รายการ' }}</strong><span v-if="row.status" class="pill">{{ statusName(row.status) }}</span></div><p v-if="row.body||row.detail||row.reason" class="text-sm text-slate-500 my-2">{{ row.body||row.detail||row.reason }}</p><p v-if="row.created_at" class="text-xs text-slate-400">{{ date(row.created_at) }}</p>
<div v-if="section==='documents'" class="mt-3 space-y-2"><p>สัญญา {{ date(row.start_date) }} – {{ date(row.end_date) }}</p><p>ค่าเช่า {{ currency(row.rent) }} · เงินประกัน {{ currency(row.deposit) }}</p><p>{{ row.sign_mode==='paper'?'เอกสารตัวจริง':'ลงนามอิเล็กทรอนิกส์' }} · {{ statusName(row.sign_status) }}</p><a v-if="row.document_key" class="brand block" :href="`/api/contracts/${row.id}/file`" target="_blank" rel="noopener">อ่าน PDF สัญญา</a><a v-if="row.sign_status==='signed'" class="brand block" :href="`/api/contracts/${row.id}/signature`" target="_blank" rel="noopener">ดูหลักฐานการลงนาม</a><Button v-if="row.sign_mode==='electronic'&&row.document_key&&row.sign_status==='pending'" class="brand-bg text-white w-full" @click="act('sign',row)">ลงนามอิเล็กทรอนิกส์</Button></div>
<Button v-if="section==='announcements'&&!row.read" variant="outline" size="sm" class="mt-3" @click="act('announcement-read',row)">รับทราบประกาศ</Button><Button v-if="section==='rules'&&!row.read" variant="outline" size="sm" class="mt-3" @click="act('rule-read',row)">อ่านและรับทราบ</Button><Button v-if="section==='moveouts'&&row.status==='settlement'&&!row.acknowledged_at" variant="outline" size="sm" class="mt-3" @click="act('ack',row)">รับทราบยอดคืนประกัน</Button>
</CardContent></Card><p v-if="!(section==='incidents'?(data?.incidents as Row[]||[]):items).length" class="text-slate-500">ยังไม่มีรายการ</p></template>
</main><nav class="bottom-bar" aria-label="เมนูผู้พัก"><RouterLink v-for="link in menu" :key="link.id" :to="`/app/${link.id}`"><component :is="link.icon" :size="21" />{{ link.label }}</RouterLink></nav><FormDialog v-if="form" :title="form.title" :fields="form.fields" :save="form.save" :note="form.note" @close="form=null" /></div></template>
